with with_windows as (select *, dense_rank() over (partition by device_code order by pressure desc nulls first) as pressure_dense_rank, first_value(temp_c, true) over (order by temp_c, id rows between unbounded preceding and current row) as first_known_temp_c, first_value(temp_c, true) over (partition by device_code order by humidity, id rows between unbounded preceding and current row) as first_known_temp_c_2 from device_readings) select id, device_code, reading_ts, temp_c, humidity, pressure, firmware from with_windows order by reading_ts desc nulls first;
